\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{tikz}
\usepackage{booktabs}
\pagestyle{empty}

%% ── Color Palette: Deep Navy / Teal / Cyan ──
\definecolor{primary}{HTML}{0B2545}
\definecolor{secondary}{HTML}{0D7E8A}
\definecolor{accent}{HTML}{0096CC}
\definecolor{accentlt}{HTML}{00B4D8}
\definecolor{bgposter}{HTML}{E8F3F8}
\definecolor{navybg}{HTML}{DDE9F2}
\definecolor{tealbg}{HTML}{D9EFF1}
\definecolor{cyanbg}{HTML}{DAF0F7}
\definecolor{navytitlebg}{HTML}{C8DCF0}
\definecolor{tealtitlebg}{HTML}{C0E8EB}
\definecolor{cyantitlebg}{HTML}{C0E8F5}
\definecolor{stathighlight}{HTML}{C8E6F5}
\definecolor{stathighlight2}{HTML}{C8EDE2}
\definecolor{stathighlight3}{HTML}{C8DCF0}
\definecolor{stathighlight4}{HTML}{CCE4CC}
\definecolor{textdark}{HTML}{0D1B2A}
\definecolor{textgray}{HTML}{3A5068}
\definecolor{highlightbg}{HTML}{0B2545}

\pagecolor{bgposter}
\color{textdark}

%% ── List Styling ──
\setlist[itemize]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{secondary}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=22pt, itemsep=5pt, parsep=0pt, topsep=2pt,
  label={\color{primary}\bfseries\arabic*.}}

%% ── Horizontal Bar Macro (overlapping rules) ──
%% Args: {Label}{Number/Text}{fraction 0..1 for bar width}
\newcommand{\hbar}[3]{%
  {\fontsize{24}{29}\selectfont #1}\hfill{\fontsize{24}{29}\selectfont\bfseries\color{accent}#2}\\[-1pt]%
  {\color{secondary!28}\rule{\linewidth}{7pt}}\\[-7pt]%
  {\color{accent}\rule{#3\linewidth}{7pt}}\\[4pt]%
}

%% ── Platform Bar Macro ──
\newcommand{\platbar}[3]{%
  {\fontsize{24}{29}\selectfont\bfseries\color{textdark} #1}\hfill%
  {\fontsize{24}{29}\selectfont\color{secondary}\bfseries #2}\\[-1pt]%
  {\color{secondary!22}\rule{\linewidth}{6pt}}\\[-6pt]%
  {\color{secondary}\rule{#3\linewidth}{6pt}}\\[5pt]%
}

%% ── Card Styles (left accent stripe) ──
\tcbset{
  navycard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=navybg,
    borderline west={5pt}{0pt}{primary},
    left=14pt, right=13pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{primary},
    coltitle=primary, colbacktitle=navytitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={primary!35},
    valign=top, drop shadow={opacity=0.14},
  },
  tealcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=tealbg,
    borderline west={5pt}{0pt}{secondary},
    left=14pt, right=13pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{secondary},
    coltitle=secondary, colbacktitle=tealtitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={secondary!35},
    valign=top, drop shadow={opacity=0.14},
  },
  cyancard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cyanbg,
    borderline west={5pt}{0pt}{accent},
    left=14pt, right=13pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{accent!80!black},
    coltitle=accent!80!black, colbacktitle=cyantitlebg,
    toptitle=5pt, bottomtitle=5pt,
    titlerule=2pt, titlerule style={accent!35},
    valign=top, drop shadow={opacity=0.14},
  },
  highlightcard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=primary!16!white,
    borderline west={6pt}{0pt}{primary},
    left=14pt, right=13pt, top=3pt, bottom=3pt,
    fonttitle=\fontsize{33}{41}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=primary,
    toptitle=5pt, bottomtitle=5pt,
    valign=top, drop shadow={opacity=0.20},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=0mm},
]

%%════════════════════════════════════
%% TITLE BAR
%%════════════════════════════════════
\posterbox[
  enhanced, colback=primary, colframe=primary,
  arc=0pt, boxrule=0pt,
  left=36pt, right=36pt, top=10pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.28}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{66}{78}\selectfont\bfseries\color{white}%
    GLOBAL INTERNET USAGE}\\[7pt]
  {\fontsize{28}{36}\selectfont\color{white!78}%
    A Cross-Country Comparison of the World's Digital Economies
    \enspace\textbullet\enspace 2025}
}

%%════════════════════════════════════
%% STATS BANNER
%%════════════════════════════════════
\posterbox[
  enhanced, colback=primary!9!bgposter, boxrule=0pt, arc=0pt,
  left=10pt, right=10pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={3pt}{0pt}{primary!28},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  %% Stat 1
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!55}{stathighlight}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{primary} 5.56B}\\[3pt]%
      {\fontsize{19}{24}\selectfont\color{textdark} Global Internet Users}%
      \vspace{5pt}}}
  \end{minipage}\hfill
  %% Stat 2
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{secondary!55}{secondary!14!white}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{secondary} 68\%}\\[3pt]%
      {\fontsize{19}{24}\selectfont\color{textdark} World Population Online}%
      \vspace{5pt}}}
  \end{minipage}\hfill
  %% Stat 3
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{accent!55}{cyanbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{accent!85!black} 143}\\[3pt]%
      {\fontsize{19}{24}\selectfont\color{textdark} Min/Day Social Media}%
      \vspace{5pt}}}
  \end{minipage}\hfill
  %% Stat 4
  \begin{minipage}[c]{0.235\linewidth}\centering
    \fcolorbox{primary!45}{stathighlight3}{\parbox{0.88\linewidth}{%
      \centering\vspace{5pt}%
      {\fontsize{50}{60}\selectfont\bfseries\color{primary} \$8.0T}\\[3pt]%
      {\fontsize{19}{24}\selectfont\color{textdark} E-Commerce by 2027}%
      \vspace{5pt}}}
  \end{minipage}
}

%%════════════════════════════════════
%% COL 1 — DIGITAL POPULATION
%%════════════════════════════════════
\posterbox[navycard, title={The World's Digital Population}
]{name=digpop, column=1, between=row5 and row12}{
  \fontsize{25}{33}\selectfont

  %% China + India special callout
  \colorbox{primary!20}{\parbox{0.955\linewidth}{%
    \centering\vspace{5pt}%
    {\fontsize{27}{34}\selectfont\bfseries\color{white}%
      China + India = \textasciitilde{}36\% of all internet users}\\[4pt]%
    {\fontsize{23}{28}\selectfont\color{white!85}%
      China:\ \textbf{1.09 billion}
      \quad\textbullet\quad
      India:\ \textbf{900 million}}%
    \vspace{5pt}%
  }}

  \vspace{9pt}
  {\fontsize{24}{30}\selectfont\bfseries\color{primary}%
    Top 10 Countries by Online Population}\\[5pt]

  \renewcommand{\arraystretch}{1.50}
  \fontsize{21}{27}\selectfont
  \begin{tabular}{@{}l r r@{}}
    \rowcolor{primary!22}
    {\bfseries\color{white} Country} &
    {\bfseries\color{white} Online Users} &
    {\bfseries\color{white} Penetration} \\
    \rowcolor{accent!18} China         & \bfseries 1.09B & 76\% \\
    \rowcolor{accent!9}  India         & \bfseries 900M  & 62\% \\
    \rowcolor{accent!18} United States & 320M            & 95\% \\
    \rowcolor{accent!9}  Indonesia     & 220M            & 78\% \\
    \rowcolor{accent!18} Brazil        & 190M            & 88\% \\
    \rowcolor{accent!9}  Japan         & 118M            & 95\% \\
    \rowcolor{accent!18} Nigeria       & 115M            & 52\% \\
    \rowcolor{accent!9}  Germany       & 80M             & 96\% \\
    \rowcolor{accent!18} United Kingdom& 66M             & 97\% \\
    \rowcolor{accent!9}  South Korea   & 50M             & 98\% \\
  \end{tabular}
}

%%════════════════════════════════════
%% COL 1 — PENETRATION RATES
%%════════════════════════════════════
\posterbox[tealcard, title={Internet Penetration Rates by Country}
]{name=penetration, column=1, between=row12 and row20}{
  \fontsize{25}{32}\selectfont

  {\fontsize{21}{27}\selectfont\color{textgray}\itshape
    Ranked highest to lowest — showing the connectivity gap
    between developed and emerging economies.}\\[7pt]

  \hbar{South Korea}{98\%}{0.98}
  \hbar{United Kingdom}{97\%}{0.97}
  \hbar{Germany}{96\%}{0.96}
  \hbar{United States}{95\%}{0.95}
  \hbar{Japan}{95\%}{0.95}
  \hbar{Brazil}{88\%}{0.88}
  \hbar{Indonesia}{78\%}{0.78}
  \hbar{China}{76\%}{0.76}
  \hbar{India}{62\%}{0.62}
  \hbar{Nigeria}{52\%}{0.52}

  \vspace{4pt}
  \colorbox{secondary!20}{\parbox{0.955\linewidth}{%
    \vspace{5pt}%
    {\fontsize{22}{28}\selectfont\bfseries\color{secondary}%
      $\Rightarrow$\ Key Insight:}\ %
    {\fontsize{22}{28}\selectfont\color{textdark}%
      Northern Europe \& East Asia lead; Sub-Saharan Africa
      \& South Asia hold the largest growth potential.}%
    \vspace{5pt}%
  }}
}

%%════════════════════════════════════
%% COL 2 — SOCIAL MEDIA USAGE
%%════════════════════════════════════
\posterbox[cyancard, title={How People Spend Time Online}
]{name=socialmedia, column=2, between=row5 and row13}{
  \fontsize{25}{33}\selectfont

  \colorbox{accent!20}{\parbox{0.955\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{46}{55}\selectfont\bfseries\color{primary} 143 minutes}\\[4pt]%
    {\fontsize{21}{27}\selectfont\color{textdark}%
      average daily social media usage in 2025,
      up from~just 90 min in 2012}%
    \vspace{6pt}%
  }}

  \vspace{11pt}
  {\fontsize{24}{30}\selectfont\bfseries\color{accent!80!black}
    Top Platforms by Monthly Active Users}\\[7pt]

  \platbar{Facebook}{3.1B MAU}{1.00}
  \platbar{YouTube}{2.5B MAU}{0.81}
  \platbar{WhatsApp}{2.4B MAU}{0.77}
  \platbar{Instagram}{2.0B MAU}{0.65}
  \platbar{TikTok}{1.6B MAU}{0.52}

  \vspace{5pt}
  \begin{itemize}[itemsep=6pt]
    \item Latin America \& Southeast Asia: \textbf{highest} daily engagement
    \item Japan \& Western Europe: comparatively \textbf{lower} usage
    \item Mobile accounts for \textbf{60\%+} of all web traffic globally
  \end{itemize}
}

%%════════════════════════════════════
%% COL 2 — DIGITAL ECONOMY
%%════════════════════════════════════
\posterbox[highlightcard, title={The Digital Economy Impact}
]{name=economy, column=2, between=row13 and row20}{
  \fontsize{25}{33}\selectfont

  %% E-commerce growth
  \colorbox{accent!22}{\parbox{0.955\linewidth}{%
    \vspace{5pt}%
    {\fontsize{23}{29}\selectfont\bfseries\color{primary}
      Global Retail E-Commerce}\\[5pt]%
    {\fontsize{34}{42}\selectfont\bfseries\color{textdark}\$6.3T}%
    {\fontsize{21}{27}\selectfont\color{textgray}\ (2024 est.)}%
    \quad%
    {\fontsize{28}{34}\selectfont\color{accent}$\longrightarrow$}%
    \quad%
    {\fontsize{34}{42}\selectfont\bfseries\color{primary}\$8.0T}%
    {\fontsize{21}{27}\selectfont\color{textgray}\ (2027 proj.)}%
    \vspace{5pt}%
  }}

  \vspace{8pt}

  %% AI market
  \colorbox{secondary!20}{\parbox{0.955\linewidth}{%
    \vspace{5pt}%
    {\fontsize{23}{29}\selectfont\bfseries\color{secondary}
      AI Market Growth}\\[4pt]%
    {\fontsize{26}{32}\selectfont\color{textdark}%
      \textbf{\$240B}\ (2023)\ $\to$\ \textbf{\$800B+}\ (2030)}%
    \vspace{5pt}%
  }}

  \vspace{9pt}
  \begin{itemize}[itemsep=7pt]
    \item E-commerce: \textbf{20\%+} of global retail sales
    \item Data generated: \textbf{180+ zettabytes} by 2025
    \item Digital economy drives demand for connectivity
    \item Asia dominates absolute online population
    \item Connectivity gaps = \textbf{economic opportunity}
  \end{itemize}

  \vspace{9pt}
  \colorbox{primary!22}{\parbox{0.955\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{21}{28}\selectfont\bfseries\color{white}%
      The world's next 2 billion internet users will reshape
      the global digital economy.}%
    \vspace{6pt}%
  }}
}

\end{tcbposter}
\end{document}
